import heapq


def shortest_path(edges, start, end):
    """
    有向グラフにおける最短路をDijkstra法 で求める。

    パラメータ:
        edges: (from_node, to_node, weight) のタプルのリスト
        start: 開始ノード
        end: 終了ノード

    戻り値:
        (distance, path) のタプル
    """
    # ウエイトが負のエッジをチェック
    for from_node, to_node, weight in edges:
        if weight < 0:
            raise ValueError("Negative edge weight is not allowed")

    # start と end が同じ場合
    if start == end:
        return (0, [start])

    # 隣接リストを構築
    graph = {}
    all_nodes = set()
    for from_node, to_node, weight in edges:
        if from_node not in graph:
            graph[from_node] = []
        graph[from_node].append((to_node, weight))
        all_nodes.add(from_node)
        all_nodes.add(to_node)

    # start がグラフに存在しない場合
    if start not in graph:
        return (None, None)

    # Dijkstra法
    # dist: ノードまでの最短距離
    dist = {}
    prev = {}  # 経路の復元用：各ノードの親ノード
    visited = set()

    # 優先キュー: (distance, node)
    heap = []
    dist[start] = 0
    prev[start] = None
    heapq.heappush(heap, (0, start))

    while heap:
        current_dist, current_node = heapq.heappop(heap)

        # 既に訪問済みであればスキップ
        if current_node in visited:
            continue
        visited.add(current_node)

        # end に到達したら即座に終了できる（Dijkstraの性質上、この時点で確定）
        if current_node == end:
            # 経路を復元
            path = []
            node = end
            while node is not None:
                path.append(node)
                node = prev[node]
            path.reverse()
            return (current_dist, path)

        # 隣接するノードを探索
        if current_node in graph:
            for neighbor, weight in graph[current_node]:
                if neighbor in visited:
                    continue
                new_dist = current_dist + weight
                if neighbor not in dist or new_dist < dist[neighbor]:
                    dist[neighbor] = new_dist
                    prev[neighbor] = current_node
                    heapq.heappush(heap, (new_dist, neighbor))

    # 経路が存在しない場合
    return (None, None)
